let count=0;document.getElementById('count').onclick=()=>{document.getElementById('count-result').textContent='확인 횟수: '+(++count)};
document.getElementById('error').onclick=()=>{throw new Error('합성 버튼 실행 오류 <strong>문자 그대로</strong>')};
document.getElementById('promise').onclick=()=>{Promise.reject(new Error('합성 비동기 오류'))};
document.getElementById('flood').onclick=()=>{for(let i=1;i<=30;i++)setTimeout(()=>{throw new Error('합성 반복 오류 '+i)},0)};
document.getElementById('probe').onclick=async()=>{const lines=[];for(const [name,read] of [['parent DOM',()=>parent.document.body],['cookie',()=>document.cookie],['localStorage',()=>localStorage.length]]){try{read();lines.push(name+': UNEXPECTED allowed')}catch(e){lines.push(name+': '+e.name)}}try{await fetch('http://127.0.0.1:61651/sink/fetch');lines.push('fetch: UNEXPECTED allowed')}catch{lines.push('fetch: blocked')}const img=document.createElement('img');img.alt='차단 대상';img.src='http://127.0.0.1:61651/sink/image';document.body.append(img);document.getElementById('probe-result').textContent=lines.join('\n')};

